import {t,getLocale} from './locales.js';import {cowEffectiveGrade,cowStorageReason,cowCoolerStatus} from './cow-storage.js';
/** @param {import('./engine.js').State} state @param {import('./cow-panel.js').CowSend} send @param {HTMLElement} host */
export function renderCowStorage(state,send,host){const g=state.cow;if(!g?.visited)return;const section=document.createElement('section');section.id='cow-stored-lots';const heading=document.createElement('h3');heading.textContent=t('cowMilkStored');section.append(heading);if(g.cooler.owned){const note=document.createElement('p'),toggle=document.createElement('button'),help=document.createElement('p'),key={off:'cowCoolingOff',idle:'cowCoolingIdle',cooling:'cowCoolingActive',paused_no_funds:'cowCoolingNoFunds'}[cowCoolerStatus(state)];note.id='cow-cooling-status';note.textContent=t('cowCooling')+': '+t(key)+'. '+t('cowCoolingCredit')+': '+g.cooler.paidTicks;help.textContent=t('cowCoolingFee');toggle.type='button';toggle.className='action-button';toggle.dataset.cowAction='toggleCowCooler';toggle.textContent=t('cowToggleCooling');toggle.setAttribute('aria-pressed',String(g.cooler.enabled));toggle.addEventListener('click',()=>send('toggleCowCooler'));section.append(note,help,toggle);}if(!g.lots.length){const note=document.createElement('p');note.textContent=t('cowNoStoredMilk');section.append(note);}for(const lot of g.lots){const row=document.createElement('div'),description=document.createElement('p');row.className='cow-milk-lot';row.dataset.cowLot=lot.id;description.textContent=lot.id+' · '+(lot.remainingVolumeMl/1000).toLocaleString(getLocale(),{maximumFractionDigits:3})+' L · '+t(lot.storage==='can'?'cowStorageCan':'cowStorageCooler')+' · '+t('cowCurrentGrade')+': '+(cowEffectiveGrade(lot)||t('cowRejected'))+' · '+t('cowFreshness')+': '+lot.freshnessScore;row.append(description);const destination=lot.storage==='can'?'cooler':'can';if(g.cooler.owned){const button=document.createElement('button'),reason=cowStorageReason(state,'moveCowMilk',lot.id,destination);button.type='button';button.className='action-button';button.dataset.cowMove=lot.id;button.textContent=t(destination==='can'?'cowMoveCan':'cowMoveCooler');button.disabled=!!reason;button.title=reason?t(reason):'';button.addEventListener('click',()=>send('moveCowMilk',{cowLot:lot.id,cowStorage:destination}));row.append(button);}const discard=document.createElement('button');discard.type='button';discard.className='action-button';discard.dataset.cowDiscard=lot.id;discard.textContent=t('cowDiscardMilk');discard.addEventListener('click',()=>send('discardCowMilk',{cowLot:lot.id}));row.append(discard);section.append(row);}host.append(section);}
